ee:message.ee:set-payload:
%dw 2.0
output application/json
import try from dw::Runtime
import resolve from dw::Timezones

var fromCity  = vars.arguments.from_city default ""
var toCity    = vars.arguments.to_city   default ""
var fromTz    = resolve(fromCity)
var toTz      = resolve(toCity)
var inputTime = vars.arguments.time default "12:00"

// Wrap in try() so an invalid city/timezone produces a clean -32602 error
// instead of propagating a DataWeave exception to the global handler.
var attempt = try(() -> do {
    // Build a local date+time string anchored to the source zone's current
    // UTC offset, so "14:30" in New York is read as 14:30 EDT, not 14:30 UTC.
    var dateStr = now() as String {format: "yyyy-MM-dd"}
    var localStr = if (inputTime contains "T")
        inputTime
    else
        dateStr ++ "T" ++ inputTime ++ (if (inputTime contains ":") "" else ":00") ++ ":00"
    var fromOffset = (now() >> (fromTz as TimeZone)) as String {format: "XXX"}
    var sourceZoned = (localStr ++ fromOffset) as DateTime
    var targetZoned = sourceZoned >> (toTz as TimeZone)
    var sourceDisplay = sourceZoned >> (fromTz as TimeZone)
    var sourceFormatted = sourceDisplay as String {format: "h:mm a z"}
    var targetFormatted = targetZoned as String {format: "h:mm a z"}
    var sourceDay = sourceDisplay as String {format: "yyyy-MM-dd"}
    var targetDay = targetZoned as String {format: "yyyy-MM-dd"}
    var dayNote = if (targetDay > sourceDay) " (next day)"
                  else if (targetDay < sourceDay) " (previous day)"
                  else ""
    ---
    sourceFormatted ++ " = " ++ targetFormatted ++ dayNote
})
---
if (attempt.success)
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "result": {
        "content": [
            {
                "type": "text",
                "text": attempt.result
            }
        ]
    }
}
else
{
    "jsonrpc": "2.0",
    "id": vars.requestId,
    "error": {
        "code": -32602,
        "message": "Invalid city or timezone. Verify 'from_city' and 'to_city' are supported names or IANA timezone IDs."
    }
}
